<?php
if (!defined('ABSPATH')) exit;
final class Dares_Piket_Advanced {
 const OPT='dares_piket_advanced';
 static function t($name){global $wpdb;return $wpdb->prefix.'dares_piket_'.$name;}
 static function init(){
  add_action('init',[__CLASS__,'upgrade']);
  add_action('admin_menu',[__CLASS__,'menu']);
  add_action('admin_post_dares_piket_adv',[__CLASS__,'post']);
