  add_action('admin_post_dares_piket_ical',[__CLASS__,'ical']);
  add_action('admin_post_nopriv_dares_piket_ical',[__CLASS__,'ical']);
  add_action('admin_post_dares_piket_feed',[__CLASS__,'feed']);
  add_action('admin_post_nopriv_dares_piket_feed',[__CLASS__,'feed']);
  add_shortcode('dares_piket_portaal',[__CLASS__,'portal']);
  add_shortcode('dares_piket_statistieken',[__CLASS__,'stats']);
  add_shortcode('dares_piket_qr',[__CLASS__,'qr']);
  add_action('dares_piket_tick',[__CLASS__,'tick']);
  add_action('rest_api_init',[__CLASS__,'api']);
  add_action('dares_piket_after_transfer',[__CLASS__,'transfer_notice'],10,7);
  add_action('admin_post_dares_piket_mail_test',[__CLASS__,'mail_test']);
  add_filter('cron_schedules',[__CLASS__,'cron_schedules']);
  add_action('wp_footer',[__CLASS__,'footer']);
 }
 static function install(){global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$c=$wpdb->get_charset_collate();
  dbDelta('CREATE TABLE '.self::t('meta').' (person_id bigint(20) unsigned NOT NULL, user_id bigint(20) unsigned NOT NULL DEFAULT 0, telegram_chat varchar(100) NOT NULL DEFAULT "", backup_person_id bigint(20) unsigned NOT NULL DEFAULT 0, PRIMARY KEY (person_id), KEY user_id (user_id)) '.$c.';');
  dbDelta('CREATE TABLE '.self::t('absence').' (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, person_id bigint(20) unsigned NOT NULL, start_at datetime NOT NULL, end_at datetime NOT NULL, note varchar(190) NOT NULL DEFAULT "", PRIMARY KEY (id), KEY person_id (person_id)) '.$c.';');
  dbDelta('CREATE TABLE '.self::t('confirm').' (shift_id bigint(20) unsigned NOT NULL, person_id bigint(20) unsigned NOT NULL, confirmed_at datetime NOT NULL, user_id bigint(20) unsigned NOT NULL, PRIMARY KEY (shift_id)) '.$c.';');
  dbDelta('CREATE TABLE '.self::t('notifications').' (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, event_key varchar(190) NOT NULL, sent_at datetime NOT NULL, PRIMARY KEY (id), UNIQUE KEY event_key (event_key)) '.$c.';');
  if(empty(self::opts()['ical_secret'])){ $o=self::opts();$o['ical_secret']=bin2hex(random_bytes(24));update_option(self::OPT,$o,false);}
  if(wp_next_scheduled('dares_piket_tick'))wp_clear_scheduled_hook('dares_piket_tick');wp_schedule_event(time()+60,'dares_piket_5min','dares_piket_tick');
  update_option('dares_piket_adv_schema','1.4.3');
 }
 static function upgrade(){if(get_option('dares_piket_adv_schema')!=='1.4.3')self::install();}
 static function cron_schedules($s){$s['dares_piket_5min']=['interval'=>300,'display'=>'Iedere vijf minuten (DARES piket)'];return $s;}
 static function opts(){return wp_parse_args((array)get_option(self::OPT,[]),['telegram_token'=>'','telegram_chat'=>'','notify_mail'=>1,'notify_telegram'=>0,'hours_before'=>24,'alarm_url'=>'','alarm_key'=>'','alarm_status'=>'','auto_enabled'=>0,'auto_group'=>0,'auto_people'=>[],'auto_start'=>'','auto_time'=>'18:00','auto_days'=>7,'auto_weeks'=>8,'ical_secret'=>'']);}
 static function save_opts($x){$o=self::opts();foreach(['telegram_token','telegram_chat','alarm_url','alarm_key'] as $key)if(isset($x[$key]))$o[$key]=sanitize_text_field(wp_unslash($x[$key]));foreach(['notify_mail','notify_telegram','auto_enabled'] as $k)$o[$k]=empty($x[$k])?0:1;$o['hours_before']=min(168,max(1,absint($x['hours_before']??24)));$selected=array_map('absint',(array)($x['auto_people']??[]));$orders=(array)($x['auto_order']??[]);$ranked=[];foreach(array_unique($selected) as $pid){if(!$pid)continue;$ranked[]=['id'=>$pid,'order'=>max(0,min(9999,absint($orders[$pid]??9999)))];}usort($ranked,static function($a,$b){return ($a['order']<=>$b['order'])?:($a['id']<=>$b['id']);});$o['auto_people']=array_column($ranked,'id');$o['auto_start']=sanitize_text_field(wp_unslash($x['auto_start']??''));$o['auto_time']='18:00';$o['auto_days']=7;$o['auto_weeks']=min(52,max(1,absint($x['auto_weeks']??8)));update_option(self::OPT,$o,false);}
 static function menu(){add_submenu_page('dares-piketrooster','Uitbreidingen','Uitbreidingen','manage_options','dares-piket-advanced',[__CLASS__,'admin']);}
 static function overlap($start,$end,$exclude=0){global $wpdb;$t=self::t('shifts');return (bool)$wpdb->get_var($wpdb->prepare("SELECT id FROM $t WHERE start_at < %s AND end_at > %s AND id <> %d LIMIT 1",$end,$start,$exclude));}
 static function form_open($kind){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dares_piket_adv"><input type="hidden" name="kind" value="'.esc_attr($kind).'">';wp_nonce_field('dares_piket_adv_'.$kind);}
 static function admin(){if(!current_user_can('manage_options'))wp_die('Geen toegang');global $wpdb;$o=self::opts();$people=Dares_Piketrooster::people();$groups=Dares_Piketrooster::groups();$metas=$wpdb->get_results('SELECT * FROM '.self::t('meta'),OBJECT_K);$abs=$wpdb->get_results('SELECT a.*,p.name FROM '.self::t('absence').' a LEFT JOIN '.self::t('people').' p ON p.id=a.person_id ORDER BY a.start_at DESC LIMIT 100');
  echo '<div class="wrap"><h1>Dares Piketrooster — uitbreidingen v1.4.3</h1><p>De bestaande groepen, diensten, widget en overdrachten blijven intact. Plan organisatiebreed nooit twee diensten tegelijk.</p>';
  if(isset($_GET['result']))echo '<div class="notice notice-info"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['result']))).'</p></div>';
  echo '<h2>Instellingen en koppelingen</h2>';self::form_open('settings');echo '<table class="form-table"><tbody>';
  foreach(['notify_mail'=>'E-mailmeldingen inschakelen','notify_telegram'=>'Telegrammeldingen inschakelen','auto_enabled'=>'Automatisch rooster activeren'] as $key=>$label)echo '<tr><th>'.esc_html($label).'</th><td><input type="checkbox" name="'.esc_attr($key).'" value="1" '.checked($o[$key],1,false).'></td></tr>';
  foreach(['hours_before'=>'Herinnering uren vooraf','telegram_chat'=>'Telegram groeps-chat-ID','telegram_token'=>'Telegram bot token','alarm_url'=>'DARES Alarmstatus API-URL (HTTPS)','alarm_key'=>'Alarmstatus API-sleutel (optioneel)'] as $key=>$label)echo '<tr><th>'.esc_html($label).'</th><td><input class="regular-text" '.($key==='telegram_token'||$key==='alarm_key'?'type="password" autocomplete="off"':'type="text"').' name="'.esc_attr($key).'" value="'.esc_attr($o[$key]).'"></td></tr>';
  echo '<tr><th>Automatisch rooster — medewerkers</th><td><p>Selecteer de personen die deelnemen en bepaal hun volgorde. De groep wordt per dienst automatisch gekoppeld aan de groep van de gekozen persoon.</p><table class="widefat striped" style="max-width:650px"><thead><tr><th>Meedoen</th><th>Medewerker</th><th>Groep</th><th>Volgorde</th></tr></thead><tbody>';
  $selected=array_map('intval',(array)$o['auto_people']);foreach($people as $p){if(empty($p->active))continue;$groupname='';foreach($groups as $g)if((int)$g->id===(int)$p->group_id){$groupname=$g->name;break;}$pos=array_search((int)$p->id,$selected,true);echo '<tr><td><input type="checkbox" name="auto_people[]" value="'.esc_attr($p->id).'" '.checked($pos!==false,true,false).'></td><td>'.esc_html($p->name).'</td><td>'.esc_html($groupname).'</td><td><input type="number" min="1" max="9999" style="width:90px" name="auto_order['.esc_attr($p->id).']" value="'.esc_attr($pos===false?'':$pos+1).'" placeholder="—"></td></tr>';}
  echo '</tbody></table><p class="description">De volgorde wordt herhaald. Bij afwezigheid wordt de volgende beschikbare persoon geprobeerd. Bestaande diensten en handmatige wijzigingen blijven intact.</p></td></tr>';
  echo '<tr><th>Vaste dienstwisseling</th><td><strong>Maandag 18:00</strong> — iedere 7 dagen. Begin op een maandag; een andere startdatum wordt doorgeschoven naar de eerstvolgende maandag.</td></tr>';
  foreach(['auto_start'=>'Begin (YYYY-MM-DD)','auto_weeks'=>'Aantal diensten vooruit'] as $key=>$label)echo '<tr><th>'.esc_html($label).'</th><td><input name="'.esc_attr($key).'" value="'.esc_attr($o[$key]).'"></td></tr>';
  echo '</tbody></table><p><button class="button button-primary">Instellingen bewaren</button></p></form>';
  echo '<h2>E-mail testen</h2><p>Verstuur een proefbericht via de ingestelde WordPress-mailfunctie. De uitslag controleert of WordPress de mail accepteert, niet of deze daadwerkelijk is bezorgd.</p>';
  echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dares_piket_mail_test">';wp_nonce_field('dares_piket_mail_test');echo '<label>Testadres <input type="email" required name="test_email" value="'.esc_attr(wp_get_current_user()->user_email).'" class="regular-text"></label> <button class="button">Verstuur testmail</button></form>';
  echo '<p>Telegram werkt pas met een zelf aangemaakte bot, correct chat-ID en toestemming voor meldingen. De Alarmstatus-koppeling leest alleen een expliciet ingestelde HTTPS JSON-endpoint (veld <code>status</code>).</p>';
  self::form_open('generate');echo '<button class="button">Genereer ontbrekende diensten volgens roosterinstellingen</button></form>';
  echo '<h2>Toekomstig rooster herstellen</h2><p><strong>Let op:</strong> vervangt uitsluitend toekomstige diensten vanaf de eerstvolgende maandag 18:00, ook handmatig ingeplande toekomstige diensten. Lopende en historische diensten blijven bestaan. De vervangen records worden eerst als back-up opgeslagen. Controleer vooraf de ingestelde medewerkersvolgorde.</p>';
  self::form_open('repair');echo '<label><input type="checkbox" name="confirm_repair" value="1" required> Ik begrijp dat toekomstige diensten worden vervangen</label> <button class="button button-secondary" onclick="return confirm(\'Het toekomstige rooster vanaf de eerstvolgende maandag 18:00 vervangen?\')">Herstel toekomstig rooster (maandag 18:00)</button></form>';
  echo '<h2>Medewerkers koppelen en back-up piket</h2><p>Een WordPress-account is nodig voor persoonlijke bevestiging en het medewerkersportaal. Gebruik een back-up uit dezelfde organisatie; die wordt getoond maar neemt niet automatisch over.</p>';
  foreach($people as $p){$m=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::t('meta').' WHERE person_id=%d',$p->id));self::form_open('person');echo '<input type="hidden" name="person_id" value="'.esc_attr($p->id).'"><strong>'.esc_html($p->name).'</strong> · WordPress gebruiker <select name="user_id"><option value="0">Niet gekoppeld</option>';foreach(get_users(['fields'=>['ID','display_name'],'number'=>500]) as $u)echo '<option value="'.esc_attr($u->ID).'" '.selected((int)($m->user_id??0),(int)$u->ID,false).'>'.esc_html($u->display_name).' (#'.esc_html($u->ID).')</option>';echo '</select> Back-up <select name="backup_person_id"><option value="0">Geen</option>';foreach($people as $other)if($other->id!==$p->id)echo '<option value="'.esc_attr($other->id).'" '.selected((int)($m->backup_person_id??0),(int)$other->id,false).'>'.esc_html($other->name).'</option>';echo '</select> Telegram chat <input name="telegram_chat" value="'.esc_attr($m->telegram_chat??'').'"><button class="button">Opslaan</button></form><hr>';}
  echo '<h2>Vakantie en beschikbaarheid</h2>';self::form_open('absence');echo '<select name="person_id">';foreach($people as $p)echo '<option value="'.esc_attr($p->id).'">'.esc_html($p->name).'</option>';echo '</select> Van <input required type="datetime-local" name="start_at"> Tot <input required type="datetime-local" name="end_at"> <input name="note" placeholder="Reden (optioneel)"><button class="button">Afwezigheid toevoegen</button></form>';
  echo '<table class="widefat striped"><thead><tr><th>Medewerker</th><th>Van</th><th>Tot</th><th>Reden</th><th></th></tr></thead><tbody>';foreach($abs as $a){echo '<tr><td>'.esc_html($a->name).'</td><td>'.esc_html($a->start_at).'</td><td>'.esc_html($a->end_at).'</td><td>'.esc_html($a->note).'</td><td>';self::form_open('absence_delete');echo '<input type="hidden" name="id" value="'.esc_attr($a->id).'"><button class="button">Verwijderen</button></form></td></tr>';}echo '</tbody></table>';
  echo '<h2>Export / agenda</h2><p><a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=dares_piket_csv'),'dares_piket_csv')).'">Download CSV (Excel)</a> <a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=dares_piket_ical'),'dares_piket_ical')).'">Download iCal</a></p>';
  echo '<p><strong>Agenda abonnement:</strong> <input class="large-text" readonly onclick="this.select()" value="'.esc_attr(add_query_arg(['action'=>'dares_piket_feed','token'=>$o['ical_secret']],admin_url('admin-post.php'))).'"><br><small>Deze privélink is een toegangssleutel: deel hem uitsluitend met geautoriseerde medewerkers. Voor Outlook/Google/Apple Agenda: abonneer op URL.</small></p>';
  echo '<p>Shortcodes: <code>[dares_piket_portaal]</code>, <code>[dares_piket_statistieken]</code>, <code>[dares_piket_qr]</code>. REST: <code>/wp-json/dares-piket/v1/current</code> en <code>/next</code>.</p></div>';
 }
 static function redirect($msg){wp_safe_redirect(add_query_arg(['page'=>'dares-piket-advanced','result'=>$msg],admin_url('admin.php')));exit;}
 static function post(){if(!is_user_logged_in())wp_die('Log in');$kind=sanitize_key($_POST['kind']??'');check_admin_referer('dares_piket_adv_'.$kind);global $wpdb;$uid=get_current_user_id();
  if($kind==='confirm'){ $id=absint($_POST['shift_id']??0);$shift=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::t('shifts').' WHERE id=%d',$id));if(!$shift||!self::owns($shift->person_id,$uid))wp_die('Geen toegang');$wpdb->replace(self::t('confirm'),['shift_id'=>$id,'person_id'=>$shift->person_id,'confirmed_at'=>Dares_Piketrooster::now(),'user_id'=>$uid]);self::notify('confirm-'.$id,'Piket bevestigd: '.$id);wp_safe_redirect(wp_get_referer()?:home_url('/'));exit;}
  if($kind==='availability'){ $pid=absint($_POST['person_id']??0);if(!self::owns($pid,$uid)&&!current_user_can('manage_options'))wp_die('Geen toegang');$start=Dares_Piketrooster::valid_date($_POST['start_at']??'');$end=Dares_Piketrooster::valid_date($_POST['end_at']??'');if(!$start||!$end||$end<=$start)wp_die('Onjuiste periode');$wpdb->insert(self::t('absence'),['person_id'=>$pid,'start_at'=>$start,'end_at'=>$end,'note'=>'Afwezig gemeld via portaal']);wp_safe_redirect(wp_get_referer()?:home_url('/'));exit;}
  if(!current_user_can('manage_options'))wp_die('Geen toegang');
  if($kind==='settings'){self::save_opts($_POST);self::redirect('Instellingen opgeslagen');}
  if($kind==='repair'){if(empty($_POST['confirm_repair']))wp_die('Bevestiging vereist.');$result=self::repair_future();self::redirect($result);}
  if($kind==='generate'){self::generate();Dares_Piket_Rooster_Mail::send_generated();self::redirect('Automatisch rooster gecontroleerd en aangevuld');}
  if($kind==='person'){$pid=absint($_POST['person_id']??0);if(!$wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::t('people').' WHERE id=%d',$pid)))wp_die('Onbekende medewerker');$backup=absint($_POST['backup_person_id']??0);if($backup===$pid)$backup=0;$wpdb->replace(self::t('meta'),['person_id'=>$pid,'user_id'=>absint($_POST['user_id']??0),'backup_person_id'=>$backup,'telegram_chat'=>sanitize_text_field(wp_unslash($_POST['telegram_chat']??''))]);self::redirect('Medewerker gekoppeld');}
  if($kind==='absence'){$pid=absint($_POST['person_id']??0);$start=Dares_Piketrooster::valid_date($_POST['start_at']??'');$end=Dares_Piketrooster::valid_date($_POST['end_at']??'');if(!$pid||!$start||!$end||$start>=$end)wp_die('Ongeldige periode');$wpdb->insert(self::t('absence'),['person_id'=>$pid,'start_at'=>$start,'end_at'=>$end,'note'=>sanitize_text_field(wp_unslash($_POST['note']??''))]);self::redirect('Afwezigheid opgeslagen');}
  if($kind==='absence_delete'){$wpdb->delete(self::t('absence'),['id'=>absint($_POST['id']??0)]);self::redirect('Afwezigheid verwijderd');}
  wp_die('Onbekende actie');
 }
 static function owns($pid,$uid){global $wpdb;return $uid&&(bool)$wpdb->get_var($wpdb->prepare('SELECT person_id FROM '.self::t('meta').' WHERE person_id=%d AND user_id=%d',$pid,$uid));}
 static function absent($pid,$start,$end){global $wpdb;return (bool)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::t('absence').' WHERE person_id=%d AND start_at<%s AND end_at>%s LIMIT 1',$pid,$end,$start));}
 static function generate(){global $wpdb;$o=self::opts();if(!$o['auto_enabled']||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$o['auto_start']))return;
  $ids=array_values(array_unique(array_filter(array_map('absint',(array)$o['auto_people']))));if(!$ids)return;
  $people=[];foreach($ids as $pid){$p=$wpdb->get_row($wpdb->prepare('SELECT id,group_id,name FROM '.self::t('people').' WHERE id=%d AND active=1',$pid));if($p&&$wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::t('groups').' WHERE id=%d',$p->group_id)))$people[]=$p;}
  if(!$people)return;
  try{$start=new DateTimeImmutable($o['auto_start'].' '.$o['auto_time'].':00',wp_timezone());}catch(Throwable $e){return;}
  // Hard rule: every automatic duty begins on Monday at 18:00 and lasts exactly seven days.
  $start=$start->setTime(18,0,0);if((int)$start->format('N')!==1)$start=$start->modify('next monday');
  $days=7;$limit=min(150,max(1,(int)$o['auto_weeks']));
  for($i=0;$i<$limit;$i++){$s=$start->add(new DateInterval('P'.($i*$days).'D'));$e=$s->add(new DateInterval('P'.$days.'D'));if($e<=current_datetime())continue;$a=$s->format('Y-m-d H:i:s');$b=$e->format('Y-m-d H:i:s');if(self::overlap($a,$b))continue;
   for($j=0;$j<count($people);$j++){$p=$people[($i+$j)%count($people)];if(!self::absent($p->id,$a,$b)){$created=$wpdb->insert(self::t('shifts'),['group_id'=>$p->group_id,'person_id'=>$p->id,'start_at'=>$a,'end_at'=>$b]);
    if($created)Dares_Piket_Rooster_Mail::record_generated($p->id);
    break;}}
  }
 }

 // Explicit, administrator-approved rebuild. A backup of affected records is retained in wp_options.
 static function repair_future(){
  global $wpdb;$o=self::opts();
  if(empty($o['auto_enabled']) || empty($o['auto_people']))return 'Activeer eerst het automatische rooster en selecteer medewerkers.';
  $now=current_datetime();$cutoff=$now->modify('next monday')->setTime(18,0,0);
  if((int)$now->format('N')===1 && $now->format('H:i')<'18:00')$cutoff=$now->setTime(18,0,0);
  $boundary=$cutoff->format('Y-m-d H:i:s');$table=self::t('shifts');
  $rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM $table WHERE end_at>%s ORDER BY start_at ASC",$boundary),ARRAY_A);
  // Preflight: avoid modifying anything if the employees/configuration are invalid.
  $valid=0;foreach((array)$o['auto_people'] as $id){$found=$wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::t('people').' WHERE id=%d AND active=1',absint($id)));if($found)$valid++;}
  if(!$valid)return 'Geen actieve geselecteerde medewerkers; er is niets veranderd.';
  $backup=['created_at'=>current_time('mysql'),'boundary'=>$boundary,'shifts'=>$rows];
  update_option('dares_piket_repair_backup_'.gmdate('YmdHis'),$backup,false);
  $wpdb->query('START TRANSACTION');
  $delete=$wpdb->query($wpdb->prepare("DELETE FROM $table WHERE start_at >= %s",$boundary));
  $shorten=$wpdb->query($wpdb->prepare("UPDATE $table SET end_at=%s WHERE start_at<%s AND end_at>%s",$boundary,$boundary,$boundary));
  if($delete===false||$shorten===false){$wpdb->query('ROLLBACK');return 'Roosterherstel mislukt; geen wijzigingen doorgevoerd.';}
  $o['auto_start']=$cutoff->format('Y-m-d');$o['auto_time']='18:00';$o['auto_days']=7;
  update_option(self::OPT,$o,false);
  self::generate();
  $wpdb->query('COMMIT');
  return 'Rooster hersteld vanaf '.$cutoff->format('d-m-Y').' 18:00. '.count($rows).' eerdere toekomstige/doorlopende diensten veilig opgeslagen als back-up.';
 }
 static function shift_badges($active){global $wpdb;$m=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::t('meta').' WHERE person_id=%d',$active->person_id));$out='';if($m&&!empty($m->backup_person_id)){$name=$wpdb->get_var($wpdb->prepare('SELECT name FROM '.self::t('people').' WHERE id=%d',$m->backup_person_id));if($name)$out.='<p class="dares-piket-next">Back-up piket: <strong>'.esc_html($name).'</strong></p>';}$confirmed=$wpdb->get_var($wpdb->prepare('SELECT confirmed_at FROM '.self::t('confirm').' WHERE shift_id=%d',$active->id));$out.='<p class="dares-piket-next">'.($confirmed?'✓ Piket bevestigd':'○ Bevestiging nog niet ontvangen').'</p>';if(self::opts()['alarm_url']){$status=get_option('dares_piket_alarm_seen','');if($status!=='')$out.='<p class="dares-piket-next">DARES Alarmstatus: <strong>'.esc_html($status).'</strong></p>';}return $out;}
 static function portal(){if(!is_user_logged_in())return '<p>Log in om je piketdiensten en beschikbaarheid te beheren.</p>';global $wpdb;$uid=get_current_user_id();$t=self::t('shifts');$p=self::t('people');$m=self::t('meta');$rows=$wpdb->get_results($wpdb->prepare("SELECT s.*,p.name,g.name group_name FROM $t s JOIN $p p ON p.id=s.person_id JOIN $m m ON m.person_id=p.id JOIN ".self::t('groups')." g ON g.id=s.group_id WHERE m.user_id=%d AND s.end_at>%s ORDER BY s.start_at LIMIT 50",$uid,Dares_Piketrooster::now()));$out='<div class="dares-piket-calendar"><h3>Mijn piketdiensten</h3>';
  foreach($rows as $s){$out.='<div class="dares-cal-entry"><strong>'.esc_html($s->group_name).'</strong> '.esc_html($s->start_at).' t/m '.esc_html($s->end_at);$confirmed=$wpdb->get_var($wpdb->prepare('SELECT shift_id FROM '.self::t('confirm').' WHERE shift_id=%d',$s->id));if(!$confirmed){$out.='<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dares_piket_adv"><input type="hidden" name="kind" value="confirm"><input type="hidden" name="shift_id" value="'.esc_attr($s->id).'">'.wp_nonce_field('dares_piket_adv_confirm','_wpnonce',true,false).'<button type="submit">Piket bevestigen</button></form>';}else $out.=' ✓ Bevestigd';$out.='</div>';}
  if(!$rows)$out.='<p>Geen komende diensten voor jouw account.</p>';
  $mine=$wpdb->get_results($wpdb->prepare('SELECT p.id,p.name FROM '.self::t('people').' p JOIN '.$m.' m ON m.person_id=p.id WHERE m.user_id=%d',$uid));if($mine){$out.='<h3>Afwezigheid doorgeven</h3><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dares_piket_adv"><input type="hidden" name="kind" value="availability">'.wp_nonce_field('dares_piket_adv_availability','_wpnonce',true,false).'<select name="person_id">';foreach($mine as $p)$out.='<option value="'.esc_attr($p->id).'">'.esc_html($p->name).'</option>';$out.='</select> Vanaf <input type="datetime-local" name="start_at" required> Tot <input type="datetime-local" name="end_at" required> <button>Afwezig melden</button></form>';}
  return $out.'</div>';
 }
 static function stats(){if(!is_user_logged_in())return '<p>Log in om statistieken te bekijken.</p>';global $wpdb;$from=current_datetime()->modify('-1 year')->format('Y-m-d H:i:s');$rows=$wpdb->get_results($wpdb->prepare('SELECT p.name,g.name group_name,COUNT(*) count_shifts,SUM(TIMESTAMPDIFF(HOUR,s.start_at,s.end_at)) hours FROM '.self::t('shifts').' s JOIN '.self::t('people').' p ON p.id=s.person_id JOIN '.self::t('groups').' g ON g.id=s.group_id WHERE s.start_at>=%s GROUP BY s.person_id,s.group_id ORDER BY hours DESC',$from));$out='<table class="dares-piket-stats"><thead><tr><th>Naam</th><th>Groep</th><th>Diensten</th><th>Uren (afgerond)</th></tr></thead><tbody>';foreach($rows as $r)$out.='<tr><td>'.esc_html($r->name).'</td><td>'.esc_html($r->group_name).'</td><td>'.esc_html($r->count_shifts).'</td><td>'.esc_html($r->hours).'</td></tr>';return $out.'</tbody></table>';}
 static function csv(){if(!current_user_can('manage_options'))wp_die('Geen toegang');check_admin_referer('dares_piket_csv');global $wpdb;$rows=$wpdb->get_results('SELECT s.*,p.name,g.name group_name FROM '.self::t('shifts').' s JOIN '.self::t('people').' p ON p.id=s.person_id JOIN '.self::t('groups').' g ON g.id=s.group_id ORDER BY s.start_at',ARRAY_A);nocache_headers();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="dares-piketrooster.csv"');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,['Groep','Medewerker','Vanaf','Tot'],';');foreach($rows as $r){$v=[$r['group_name'],$r['name'],$r['start_at'],$r['end_at']];foreach($v as &$x)if(preg_match('/^[=+@\-\t\r]/u',(string)$x))$x="'".$x;unset($x);fputcsv($f,$v,';');}fclose($f);exit;}
 static function feed(){ $o=self::opts(); $token=isset($_GET['token'])&&is_scalar($_GET['token'])?sanitize_text_field(wp_unslash($_GET['token'])):'';if(!$token||!hash_equals($o['ical_secret'],$token))wp_die('Ongeldige kalenderlink', 'Geen toegang',['response'=>403]);self::ical_output('inline');}
 static function ical(){if(!current_user_can('manage_options'))wp_die('Geen toegang');check_admin_referer('dares_piket_ical');self::ical_output('attachment');}
 static function ical_output($disposition){global $wpdb;$rows=$wpdb->get_results('SELECT s.*,p.name,g.name group_name FROM '.self::t('shifts').' s JOIN '.self::t('people').' p ON p.id=s.person_id JOIN '.self::t('groups').' g ON g.id=s.group_id ORDER BY s.start_at LIMIT 2000');nocache_headers();header('Content-Type: text/calendar; charset=utf-8');header('Content-Disposition: '.$disposition.'; filename="dares-piketrooster.ics"');echo "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//DARES//Piketrooster//NL\r\nCALSCALE:GREGORIAN\r\n";foreach($rows as $r){$fmt=function($date){return (new DateTimeImmutable($date,wp_timezone()))->setTimezone(new DateTimeZone('UTC'))->format('Ymd\THis\Z');};$title=str_replace(["\\",',',';',"\r","\n"],['\\\\','\\,','\\;','','\\n'],$r->group_name.' - '.$r->name);echo 'BEGIN:VEVENT'."\r\n".'UID:dares-piket-'.(int)$r->id.'@'.sanitize_text_field(parse_url(home_url(),PHP_URL_HOST))."\r\n".'DTSTAMP:'.gmdate('Ymd\THis\Z')."\r\n".'DTSTART:'.$fmt($r->start_at)."\r\n".'DTEND:'.$fmt($r->end_at)."\r\n".'SUMMARY:'.$title."\r\nEND:VEVENT\r\n";}echo "END:VCALENDAR\r\n";exit;}
 static function api(){foreach(['current','next'] as $route)register_rest_route('dares-piket/v1','/'.$route,['methods'=>'GET','permission_callback'=>'__return_true','callback'=>function()use($route){$s=$route==='current'?Dares_Piketrooster::global_current():Dares_Piketrooster::global_next();return rest_ensure_response($s?['group'=>$s->group_name,'name'=>$s->name,'starts'=>$s->start_at,'ends'=>$s->end_at,'confirmed'=> (bool) self::confirmed($s->id)]:['active'=>false]);}]);register_rest_route('dares-piket/v1','/details',['methods'=>'GET','permission_callback'=>function(){return current_user_can('manage_options');},'callback'=>function(){return rest_ensure_response(['active'=>Dares_Piketrooster::global_current(),'next'=>Dares_Piketrooster::global_next()]);}]);}
 static function confirmed($id){global $wpdb;return $wpdb->get_var($wpdb->prepare('SELECT shift_id FROM '.self::t('confirm').' WHERE shift_id=%d',$id));}
 static function portal_url(){ $id=absint(get_option('dares_piket_portal_page',0));$url=$id?get_permalink($id):'';return $url?:home_url('/piket-portaal/'); }
 static function mail_test(){if(!current_user_can('manage_options'))wp_die('Geen toegang');check_admin_referer('dares_piket_mail_test');$email=sanitize_email(wp_unslash($_POST['test_email']??''));if(!is_email($email))self::redirect('Ongeldig e-mailadres.');$ok=wp_mail($email,'DARES Piketrooster — testbericht',"Dit is een testbericht vanuit DARES Piketrooster v1.4.2.\nVerzonden: ".wp_date('d-m-Y H:i:s')."\nWebsite: ".home_url('/'));self::redirect($ok?'Testmail aangeboden aan WordPress mailfunctie: '.$email:'Testmail mislukt. Controleer SMTP en WordPress error log.');}
 static function notify($key,$message,$pid=0,$subject='DARES Piketrooster'){global $wpdb;if($pid && class_exists('Dares_Piket_WhatsApp'))Dares_Piket_WhatsApp::event($key,$pid,$subject,$message);$o=self::opts();$n=self::t('notifications');$m=$pid?$wpdb->get_row($wpdb->prepare('SELECT p.email,m.telegram_chat FROM '.self::t('people').' p LEFT JOIN '.self::t('meta').' m ON p.id=m.person_id WHERE p.id=%d',$pid)):null;
  $sendMail=!!$o['notify_mail']&&($pid?($m&&is_email($m->email)):is_email(get_option('admin_email')));$chat=$m&&!empty($m->telegram_chat)?$m->telegram_chat:$o['telegram_chat'];$sendTelegram=!!$o['notify_telegram']&&!!$o['telegram_token']&&!!$chat;
  if(!$sendMail&&!$sendTelegram)return false;
  $key=substr($key,0,190);if($wpdb->get_var($wpdb->prepare('SELECT event_key FROM '.$n.' WHERE event_key=%s',$key)))return true;
  $delivered=false;if($sendMail){$to=$pid?$m->email:get_option('admin_email');$delivered=(bool)wp_mail($to,$subject,$message);}
  if($sendTelegram){$response=wp_remote_post('https://api.telegram.org/bot'.rawurlencode($o['telegram_token']).'/sendMessage',['timeout'=>12,'body'=>['chat_id'=>$chat,'text'=>$message]]);if(!is_wp_error($response)&&wp_remote_retrieve_response_code($response)===200)$delivered=true;}
  if($delivered)$wpdb->insert($n,['event_key'=>$key,'sent_at'=>Dares_Piketrooster::now()]);return $delivered;
 }
 static function tick(){global $wpdb;$o=self::opts();$now=current_datetime();$stamp=$now->format('Y-m-d H:i:s');$future=$now->modify('+'.(int)$o['hours_before'].' hours');$shifts=self::t('shifts');$people=self::t('people');
  if($o['auto_enabled'])self::generate();
  $rows=$wpdb->get_results($wpdb->prepare("SELECT s.*,p.name FROM $shifts s JOIN $people p ON p.id=s.person_id WHERE s.start_at>%s AND s.start_at<=%s ORDER BY s.start_at LIMIT 200",$stamp,$future->format('Y-m-d H:i:s')));
  foreach($rows as $r){$hours=(int)$o['hours_before'];$text="Beste ".$r->name.",\n\nJe bent ingeroosterd voor piket vanaf ".$r->start_at." tot ".$r->end_at.".\nBevestig je piketdienst in het piketportaal: ".self::portal_url()."\n\nDeze bevestiging is administratief en houdt de automatische dienstwisseling niet tegen.";self::notify('reminder-'.$r->id,$text,$r->person_id,'DARES: piket begint binnen '.$hours.' uur — bevestiging gevraagd');}
  $active=Dares_Piketrooster::global_current();if($active){$text="Je piketdienst is gestart.\nMedewerker: ".$active->name."\nGroep: ".$active->group_name."\nVanaf: ".$active->start_at."\nTot: ".$active->end_at."\nBevestigen: ".self::portal_url();self::notify('started-'.$active->id,$text,$active->person_id,'DARES: je hebt nu piket — bevestiging gevraagd');}
  if($o['alarm_url'])self::alarm_check();
 }
 static function alarm_check(){$o=self::opts();$url=esc_url_raw($o['alarm_url']);if(strpos($url,'https://')!==0)return;$headers=[];if($o['alarm_key'])$headers['Authorization']='Bearer '.$o['alarm_key'];$response=wp_safe_remote_get($url,['timeout'=>8,'headers'=>$headers,'limit_response_size'=>8192]);if(is_wp_error($response)||wp_remote_retrieve_response_code($response)!==200)return;$data=json_decode(wp_remote_retrieve_body($response),true);if(!is_array($data)||!isset($data['status'])||!is_scalar($data['status']))return;$status=substr(sanitize_text_field((string)$data['status']),0,100);$old=get_option('dares_piket_alarm_seen','');if($status!==$old){update_option('dares_piket_alarm_seen',$status,false);$s=Dares_Piketrooster::global_current();if($s)self::notify('alarm-'.md5($status.'|'.time()),'DARES Alarmstatus is gewijzigd naar '.$status.'; piket: '.$s->name,$s->person_id);}}
 static function transfer_notice($old,$new,$group,$oldPid=0,$newPid=0,$at='',$shiftId=0){$at=$at?:Dares_Piketrooster::now();if(class_exists('Dares_Piket_Push')){if($oldPid)Dares_Piket_Push::queue('transfer',$oldPid,'DARES: piket overgenomen',$new.' heeft je dienst overgenomen om '.$at);if($newPid)Dares_Piket_Push::queue('transfer',$newPid,'DARES: jij hebt nu piket','Dienst overgenomen om '.$at.'. Bevestig deze in het portaal.');}$subject='DARES: piket overgenomen door '.$new;$message="Je piketdienst is op ".$at." overgenomen door ".$new." (".$group.").\nJe bent vanaf dit moment niet meer de actieve piketmedewerker.";if($oldPid)self::notify('transfer-old-'.md5($oldPid.'|'.$newPid.'|'.$at),$message,$oldPid,$subject);
  $incoming="Je hebt op ".$at." de piketdienst overgenomen van ".$old." (".$group.").\nBevestig je dienst via het piketportaal: ".self::portal_url()."\nDe piketdienst is direct actief, ook zonder bevestiging.";if($newPid)self::notify('transfer-new-'.md5($oldPid.'|'.$newPid.'|'.$at),$incoming,$newPid,'DARES: jij hebt nu piket — bevestig je dienst');}
 static function qr($atts=[]){$a=shortcode_atts(['url'=>''],(array)$atts);$url=$a['url']?esc_url($a['url']):home_url('/');if(!wp_http_validate_url($url))return '';return '<div class="dares-piket-qr"><img width="180" height="180" loading="lazy" alt="QR-code piketpagina" src="'.esc_url('https://api.qrserver.com/v1/create-qr-code/?size=180x180&data='.rawurlencode($url)).'"><p><a href="'.esc_url($url).'">Open piketpagina</a></p><small>De URL van de openbare pagina wordt naar de externe QR-dienst qrserver.com gestuurd. Gebruik hier geen privé agenda-link.</small></div>';}
 static function footer(){}
}
